#include <stdio.h>
int copy_file(const char *src, const char *dst) {
    FILE *s = fopen(src, "rb");
    if (!s) { perror(src); return 1; }
    FILE *d = fopen(dst, "wb");
    if (!d) { perror(dst); fclose(s); return 1; }
    unsigned char buf[4096];
    size_t got;
    while ((got = fread(buf, 1, sizeof buf, s)) > 0) {
        if (fwrite(buf, 1, got, d) != got) { fclose(s); fclose(d); return 1; }
    }
    if (ferror(s)) { fclose(s); fclose(d); return 1; }
    fclose(s); fclose(d);
    return 0;
}

