/* 读 in.txt，算 running sum，写 out.txt */
#include <stdio.h>
int main(void){
    FILE *in=fopen("in.txt","r"); if(!in){perror("in");return 1;}
    FILE *out=fopen("out.txt","w"); if(!out){perror("out");fclose(in);return 1;}
    int x, prev=0;
    while(fscanf(in,"%d",&x)==1){ prev+=x; fprintf(out,"%d\n",prev); }
    fclose(in); fclose(out); return 0;
}
